-- 005_rls_policies.sql — Enable RLS + policies
DO $$ DECLARE t TEXT; BEGIN FOR t IN SELECT unnest(ARRAY['user_profiles','addresses','bank_accounts','payment_methods','push_tokens','notification_preferences','user_sessions','user_consents','wishlist','search_history','points_transactions','categories','cities','currencies','faqs','banners','legal_pages','plans','tax_rates','shipping_methods','delivery_zones','product_tags','loyalty_tiers','achievements','products','suppliers','stores','orders','order_items','supplier_orders','supplier_order_items','commissions','ledger_entries','invoices','transactions','delivery_tasks','relationships','notifications','app_settings','admin_actions','reviews','coupons','refunds','chat_messages']) LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); END LOOP; END $$;
